// raceLimit is a race's row of raceLimits. Strength limits used to differ by
// gender (the women's are kept in the comments); everyone gets the men's now.
type raceLimit struct {
	StrMin, StrMax byte
	Str00Max       byte    // exceptional strength cap for fighters with 18
	Min, Max       [5]byte // intelligence, wisdom, dexterity, constitution, charisma
}

// ageDice is a starting age: Base + Count dice of Sides.
type ageDice struct {
	Base         uint16
	Count, Sides byte
}

// limits returns the race's minimum and maximum of ability i (0 strength).
func (r raceLimit) limits(i int) (lo, hi byte) {
	if i == 0 {
		return r.StrMin, r.StrMax
	}
	return r.Min[i-1], r.Max[i-1]
}

